INSERT INTO train_seat_stock (
    id, train_no, run_date, seat_type, price, total, remain, version, create_time, update_time
) VALUES (
    #{id}, #{trainNo}, #{runDate}, #{seatType}, #{price}, #{total}, #{remain}, 0, #{createTime}, #{updateTime}
)

mapper.select:
SELECT  FROM train_seat_stock
WHERE train_no = #{trainNo} AND run_date = #{runDate} AND seat_type = #{seatType}
LIMIT 1

SELECT  FROM train_seat_stock
WHERE train_no = #{trainNo} AND run_date = #{runDate}
ORDER BY FIELD(seat_type, 'BUSINESS', 'FIRST', 'SECOND', 'STAND')

SELECT  FROM train_seat_stock
WHERE train_no = #{trainNo}
ORDER BY run_date ASC, FIELD(seat_type, 'BUSINESS', 'FIRST', 'SECOND', 'STAND')

mapper.update:
UPDATE train_seat_stock
SET remain = remain - #{num}, version = version + 1
WHERE train_no = #{trainNo}
  AND run_date  = #{runDate}
  AND seat_type = #{seatType}
  AND version   = #{version}
  AND remain    >= #{num}

UPDATE train_seat_stock
SET remain = remain + #{num}, version = version + 1
WHERE train_no = #{trainNo}
  AND run_date  = #{runDate}
  AND seat_type = #{seatType}
  AND version   = #{version}
